begin;
create extension if not exists pgtap with schema extensions;
select plan(14);
select ok(not has_table_privilege('authenticated','public.ride_offers','insert'),'Rides require authorised transactional APIs');
select ok(not has_table_privilege('authenticated','public.ride_offers','update'),'Drivers cannot bypass capacity checks');
select ok(not has_table_privilege('authenticated','public.ride_reservations','insert'),'Passengers cannot bypass atomic booking');
select ok(not has_table_privilege('authenticated','public.ride_reservations','update'),'Passengers cannot forge booking actors');
select ok(not has_table_privilege('authenticated','public.partner_relationships','insert'),'Consent cannot be directly forged');
select ok(not has_table_privilege('authenticated','public.partner_participants','insert'),'Exclusive partner slots require acceptance');
select ok(not has_table_privilege('authenticated','public.transport_operations','select'),'Idempotency ledger is private');
select ok(not has_table_privilege('authenticated','public.ride_reservation_history','select'),'Audit history is operator-only');
select ok(not has_function_privilege('anon','public.book_ride(uuid,text,uuid)','execute'),'Anonymous users cannot book');
select ok(not has_function_privilege('anon','public.switch_ride(uuid,text,uuid,uuid[])','execute'),'Anonymous users cannot switch rides');
select ok(not has_function_privilege('anon','public.respond_partner(uuid,text)','execute'),'Anonymous users cannot accept consent');
select ok(not has_function_privilege('authenticated','private.reserve_ride(uuid,text,uuid,boolean,uuid[])','execute'),'Private helper is not a public bypass');
select ok((select prosecdef from pg_proc where oid='private.check_partner_slots()'::regprocedure),'Deferred constraint validates both private participant slots');
select ok(exists(select 1 from pg_indexes where schemaname='public' and indexname='one_confirmed_seat_per_post' and indexdef ilike '%UNIQUE%'),'Active passenger identity stays unique across all rides on a post');
select * from finish();
rollback;
